import React from 'react'
import { Card, Row, Col, Button } from 'antd'
import FinishStyle from './finish.style'
import IntlMessages from '../../../components/utility/intlMessages'


class Summary extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      claimType:
        window.sessionStorage.getItem('claimType') !== undefined ? window.sessionStorage.getItem('claimType') : []
    }
  }
  componentWillMount () {
    const { history, match, location } = this.props
    if (location.state === undefined) {
      history.push(`/policydetail/${match.params.id}`)
    }
  }
  goToPolicyList = () => {
    const { history } = this.props

    window.sessionStorage.removeItem('claimForm')
    window.sessionStorage.removeItem('claimType')
    window.sessionStorage.removeItem('claimId')
    history.push('/')
  }
  render () {
    const { state } = this.props.location
    return (
      <FinishStyle>
        <Row style={{ display: 'flex', justifyContent: 'center' }}>
          <Col xs={24} sm={24} md={12} lg={12} xl={12}>
            <Card>
              <Row>
                <Col xs={24} sm={24} md={12} lg={24} xl={24}>
                  <h2>
                    <IntlMessages id='Klaim anda berhasil dikirim' />.
                  </h2>
                  <p>
                    <IntlMessages id='No Klaim anda adalah' />
                    <strong>{state !== undefined && state.claimId}</strong>
                  </p>
                </Col>
                <Col className='btn-container' span={24}>
                  <Button
                    type='primary'
                    className='button'
                    onClick={this.goToPolicyList}
                    style={{ float: 'right', marginTop: '15px' }}
                  >
                    <IntlMessages id='Daftar Polis' />
                  </Button>
                </Col>
                <Col className='btn-container-mobile' span={24}>
                  <Button
                    type='primary'
                    className='button'
                    onClick={this.goToPolicyList}
                    style={{
                      float: 'right',
                      marginTop: '15px',
                      marginRight: '15px'
                    }}
                  >
                    <IntlMessages id='Daftar Polis' />
                  </Button>
                </Col>
              </Row>
            </Card>
          </Col>
        </Row>
      </FinishStyle>
    )
  }
}

export default Summary
